export const DELETE = Symbol('delete');

import { cloneValue } from './clone-value.mjs';

function isOrdinaryObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === null || proto === Object.prototype;
}

function validateMergeValue(value) {
  if (value === undefined || value === DELETE) {
    return;
  }
  if (value === null || typeof value === 'boolean' || typeof value === 'string') {
    return;
  }
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new TypeError('invalid number');
    }
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') {
    throw new TypeError('invalid value');
  }
  if (Array.isArray(value)) {
    for (const element of value) {
      validateMergeValue(element);
    }
    return;
  }
  if (!isOrdinaryObject(value)) {
    throw new TypeError('invalid object');
  }
  for (const key of Object.keys(value)) {
    validateMergeValue(value[key]);
  }
}

function mergeInto(target, layer) {
  for (const key of Object.keys(layer)) {
    const incoming = layer[key];
    if (incoming === undefined) {
      continue;
    }
    if (incoming === DELETE) {
      delete target[key];
      continue;
    }
    const previous = target[key];
    if (isOrdinaryObject(previous) && isOrdinaryObject(incoming)) {
      mergeInto(previous, incoming);
    } else {
      target[key] = cloneValue(incoming);
    }
  }
}

export function mergeLayers(...layers) {
  const out = {};
  for (const layer of layers) {
    if (layer === undefined) {
      continue;
    }
    if (!isOrdinaryObject(layer)) {
      throw new TypeError('invalid layer');
    }
    for (const key of Object.keys(layer)) {
      validateMergeValue(layer[key]);
    }
    mergeInto(out, layer);
  }
  return out;
}

